/*
 * SoH inference for a BMS microcontroller: C99, no heap, no dependencies
 * beyond <math.h> (tanhf). Weights come from soh_model.h, generated by
 * edge/build_c_model.py from an exported digital twin.
 *
 *   y = x . Ws + tanh(x . W1 + b1) . W2 + b2,   x = (raw - mean) / std
 *
 * Build the stdin test harness (used by edge/verify_edge.py):
 *   gcc -O2 -std=c99 -DSOH_TEST_MAIN -I edge edge/soh_infer.c -lm -o soh_infer
 */
#include <math.h>
#include "soh_model.h"

#define DQ(name, idx) ((float)SOH_##name##_Q[idx] * SOH_##name##_SCALE + SOH_##name##_MIN)

float soh_predict(const float raw[SOH_N_FEATURES])
{
    float x[SOH_N_FEATURES];
    float y = DQ(b2, 0);
    int i, j;

    for (i = 0; i < SOH_N_FEATURES; i++) {
        x[i] = (raw[i] - SOH_MEAN[i]) / SOH_STD[i];
        y += x[i] * DQ(Ws, i);
    }
    for (j = 0; j < SOH_HIDDEN; j++) {
        float z = DQ(b1, j);
        for (i = 0; i < SOH_N_FEATURES; i++)
            z += x[i] * DQ(W1, i * SOH_HIDDEN + j);
        y += tanhf(z) * DQ(W2, j);
    }
    return y;
}

#ifdef SOH_TEST_MAIN
#include <stdio.h>

/* reads SOH_N_FEATURES whitespace-separated numbers per line, prints SoH */
int main(void)
{
    float raw[SOH_N_FEATURES];
    for (;;) {
        int i;
        for (i = 0; i < SOH_N_FEATURES; i++)
            if (scanf("%f", &raw[i]) != 1)
                return 0;
        printf("%.7f\n", soh_predict(raw));
    }
}
#endif
